import { useId, useRef } from "react";
import type { KeyboardEvent, ReactNode } from "react";
import "./TabStrip.css";

export interface Tab {
  id: string;
  label: string;
}

export interface TabStripProps {
  tabs: readonly Tab[];
  selected: string;
  onSelect: (id: string) => void;
  children: ReactNode;
}

export function TabStrip({ tabs, selected, onSelect, children }: TabStripProps) {
  const baseId = useId();
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);

  const selectedIndex = tabs.findIndex((tab) => tab.id === selected);
  // Roving tabindex: the selected tab is the single stop in the tab order.
  // If the selected id matches nothing, the first tab is the stop.
  const tabStopIndex = selectedIndex >= 0 ? selectedIndex : 0;

  const tabId = (id: string) => `${baseId}-tab-${id}`;
  const panelId = `${baseId}-panel`;
  const labelledBy = tabs[tabStopIndex] ? tabId(tabs[tabStopIndex].id) : undefined;

  function moveTo(index: number) {
    const tab = tabs[index];
    if (!tab) return;
    onSelect(tab.id);
    buttons.current[index]?.focus();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const last = tabs.length - 1;
    let next: number;
    switch (event.key) {
      case "ArrowRight":
        next = index === last ? 0 : index + 1;
        break;
      case "ArrowLeft":
        next = index === 0 ? last : index - 1;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = last;
        break;
      default:
        return;
    }
    event.preventDefault();
    moveTo(next);
  }

  return (
    <div className="tab-strip">
      <div role="tablist" className="tab-strip__list">
        {tabs.map((tab, index) => (
          <button
            key={tab.id}
            ref={(el) => {
              buttons.current[index] = el;
            }}
            type="button"
            role="tab"
            id={tabId(tab.id)}
            className="tab-strip__tab"
            aria-selected={index === selectedIndex}
            aria-controls={panelId}
            tabIndex={index === tabStopIndex ? 0 : -1}
            onClick={() => onSelect(tab.id)}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            {tab.label}
          </button>
        ))}
      </div>
      <div
        role="tabpanel"
        id={panelId}
        aria-labelledby={labelledBy}
        tabIndex={0}
        className="tab-strip__panel"
      >
        {children}
      </div>
    </div>
  );
}
