  border-radius: 0.5rem 0.5rem 0 0;
  padding: 0.5rem 0.9rem;
  margin-bottom: -1px;
  cursor: pointer;
  transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease;
}

.tab-strip__tab:hover {
  color: var(--ink);
  background: var(--myelin-wash);
}

.tab-strip__tab[aria-selected="true"] {
  color: var(--ink);
  font-weight: 700;
  border-bottom-color: var(--myelin);
}

.tab-strip__panel {
  min-width: 0;
}

:root[data-motion="reduce"] .tab-strip__tab {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .tab-strip__tab {
    transition: none;
  }
}
